use std::fs;
use std::path::Path;

use crate::Preset;

const ALIASES_BEGIN: &str =
	"<!-- disguise aliases: generated by scripts/disguise-icons -->";
const ALIASES_END: &str = "<!-- end of disguise aliases -->";

pub fn resource_name(preset: &Preset) -> String {
	format!("disguise_{}", preset.id.replace('-', "_"))
}

fn alias_name(preset: &Preset) -> String {
	preset
		.id
		.split('-')
		.map(|word| {
			let mut letters = word.chars();
			letters
				.next()
				.map(|first| first.to_uppercase().chain(letters).collect())
				.unwrap_or_default()
		})
		.collect::<Vec<String>>()
		.concat()
}

fn xml_text(value: &str) -> String {
	value
		.replace('&', "&amp;")
		.replace('<', "&lt;")
		.replace('>', "&gt;")
		.replace('"', "&quot;")
}

pub fn adaptive_icon(preset: &Preset) -> String {
	let name = resource_name(preset);
	format!(
		"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<adaptive-icon xmlns:android=\"http://schemas.android.com/apk/res/android\">\n  <background android:drawable=\"@color/ic_launcher_background\"/>\n  <foreground android:drawable=\"@drawable/{name}_foreground\"/>\n  <monochrome android:drawable=\"@drawable/{name}_monochrome\"/>\n</adaptive-icon>\n"
	)
}

pub fn strings(presets: &[Preset]) -> String {
	let mut xml = String::from(
		"<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n",
	);
	for preset in presets {
		xml.push_str(&format!(
			"  <string name=\"{}\" translatable=\"false\">{}</string>\n",
			resource_name(preset),
			xml_text(&preset.name).replace('\'', "\\'")
		));
	}
	xml.push_str("</resources>\n");
	xml
}

struct Alias<'a> {
	name: &'a str,
	enabled: bool,
	icon: &'a str,
	label: &'a str,
	id: &'a str,
	notification_icon: &'a str,
}

fn alias_element(alias: &Alias) -> String {
	format!(
		"\t\t<activity-alias\n\t\t\tandroid:enabled=\"{}\"\n\t\t\tandroid:exported=\"true\"\n\t\t\tandroid:icon=\"{}\"\n\t\t\tandroid:label=\"{}\"\n\t\t\tandroid:name=\"{}\"\n\t\t\tandroid:targetActivity=\".AppActivity\">\n\t\t\t<intent-filter>\n\t\t\t\t<action android:name=\"android.intent.action.MAIN\" />\n\t\t\t\t<category android:name=\"android.intent.category.LAUNCHER\" />\n\t\t\t</intent-filter>\n\t\t\t<meta-data android:name=\"org.opengrind.disguise\" android:value=\"{}\" />\n\t\t\t<meta-data android:name=\"org.opengrind.disguise.notification_icon\" android:resource=\"{}\" />\n\t\t</activity-alias>",
		alias.enabled,
		alias.icon,
		alias.label,
		alias.name,
		alias.id,
		alias.notification_icon
	)
}

pub fn write_manifest_aliases(
	manifest: &Path,
	presets: &[Preset],
) -> Result<(), String> {
	let original = alias_element(&Alias {
		name: ".MainActivity",
		enabled: true,
		icon: "@mipmap/ic_launcher",
		label: "@string/main_activity_title",
		id: "original",
		notification_icon: "@drawable/ic_notification",
	});
	let disguises = presets.iter().map(|preset| {
		let name = resource_name(preset);
		alias_element(&Alias {
			name: &format!(".disguise.{}", alias_name(preset)),
			enabled: false,
			icon: &format!("@mipmap/{name}"),
			label: &format!("@string/{name}"),
			id: &preset.id,
			notification_icon: &format!("@drawable/{name}_notification"),
		})
	});
	let block = std::iter::once(original)
		.chain(disguises)
		.collect::<Vec<_>>()
		.join("\n");
	let text =
		fs::read_to_string(manifest).map_err(|error| error.to_string())?;
	let begin = text
		.find(ALIASES_BEGIN)
		.ok_or("AndroidManifest.xml has no disguise alias markers")?;
	let end = text
		.find(ALIASES_END)
		.filter(|end| *end > begin)
		.ok_or("AndroidManifest.xml has no disguise alias markers")?;
	let updated = format!(
		"{}\n{block}\n\t\t{}",
		&text[..begin + ALIASES_BEGIN.len()],
		&text[end..]
	);
	fs::write(manifest, updated).map_err(|error| error.to_string())
}
